mapper.select:
SELECT COUNT(1)
FROM test_case tc
JOIN project p ON p.id = tc.project_id

    AND tc.project_id = #{projectId}
    AND p.test_team = #{testTeam}

SELECT tc.project_id AS projectId, COUNT(1) AS totalCases FROM test_case tc JOIN project p ON p.id = tc.project_id
AND p.test_team = #{testTeam}
GROUP BY tc.project_id

SELECT
t.test_team AS testTeam,
COALESCE(SUM(CASE WHEN t.stat_date BETWEEN #{startDate} AND #{endDate}
             THEN t.executed_count ELSE 0 END), 0) AS executed,
COALESCE(SUM(CASE WHEN t.stat_date BETWEEN #{startDate} AND #{endDate}
             THEN t.success_count ELSE 0 END), 0) AS success,
COALESCE(SUM(CASE WHEN t.stat_date BETWEEN #{startDate} AND #{endDate}
             THEN t.fail_count ELSE 0 END), 0) AS fail,
SUM(CASE WHEN t.stat_date BETWEEN #{startDate} AND #{endDate}
         THEN t.executed_count ELSE NULL END) AS executedNonNull,
SUM(CASE WHEN t.stat_date BETWEEN #{prevStartDate} AND #{prevEndDate}
         THEN t.executed_count ELSE NULL END) AS prevExecuted
FROM execution_daily_stat t
WHERE t.stat_date BETWEEN #{prevStartDate} AND #{endDate}
GROUP BY t.test_team
ORDER BY executed DESC

SELECT p.id AS projectId, p.name AS projectName, p.system_code AS systemCode, p.test_team AS testTeam, COALESCE(cur.executed, 0) AS executed, COALESCE(cur.success, 0) AS success, COALESCE(cur.fail, 0) AS fail, cur.executed AS executedNonNull, prev.executed AS prevExecuted FROM project p LEFT JOIN ( SELECT project_id, SUM(executed_count) AS executed, SUM(success_count) AS success, SUM(fail_count) AS fail FROM execution_daily_stat WHERE stat_date BETWEEN #{startDate} AND #{endDate} GROUP BY project_id ) cur ON cur.project_id = p.id LEFT JOIN ( SELECT project_id, SUM(executed_count) AS executed FROM execution_daily_stat WHERE stat_date BETWEEN #{prevStartDate} AND #{prevEndDate} GROUP BY project_id ) prev ON prev.project_id = p.id
AND p.test_team = #{testTeam}
ORDER BY executed DESC, p.system_code

SELECT t.project_id AS projectId, COUNT(DISTINCT t.case_id) AS covered FROM execution_case_daily_stat t WHERE t.stat_date BETWEEN #{startDate} AND #{endDate}
AND t.project_id IN (SELECT id FROM project WHERE test_team = #{testTeam})
GROUP BY t.project_id

SELECT s.case_id AS caseId, tc.name AS caseName, COALESCE(SUM(s.executed_count), 0) AS executed, COALESCE(SUM(s.success_count), 0) AS success, COALESCE(SUM(s.fail_count), 0) AS fail, MIN(s.stat_date) AS firstDate, MAX(s.stat_date) AS lastDate FROM execution_case_daily_stat s LEFT JOIN test_case tc ON tc.id = s.case_id WHERE s.project_id = #{projectId} AND s.stat_date BETWEEN #{startDate} AND #{endDate}
AND tc.name LIKE CONCAT('%', #{keyword}, '%')
GROUP BY s.case_id, tc.name ORDER BY ${orderClause} LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM (
    SELECT s.case_id
    FROM execution_case_daily_stat s
    LEFT JOIN test_case tc ON tc.id = s.case_id
    WHERE s.project_id = #{projectId}
      AND s.stat_date BETWEEN #{startDate} AND #{endDate}

          AND tc.name LIKE CONCAT('%', #{keyword}, '%')

    GROUP BY s.case_id
) t

SELECT t.project_id AS projectId, t.exec_type AS execType, COALESCE(SUM(t.executed_count), 0) AS executed, COALESCE(SUM(t.success_count), 0) AS success, COALESCE(SUM(t.fail_count), 0) AS fail FROM execution_daily_stat t WHERE t.stat_date BETWEEN #{startDate} AND #{endDate}
AND t.test_team = #{testTeam}
GROUP BY t.project_id, t.exec_type
